import { useEffect, useRef, useState } from 'react';
import CustomGrid from 'components/grid_data';
import { Add } from '@mui/icons-material';
import { Box, Grid, Stack, Typography } from '@mui/material';
import columns from './columns';
import HttpService from 'components/httpService';
import AddEdit from './add_edit';
import CustomDrawer from 'components/drawer';
import { Form, Formik } from 'formik';
import api from 'components/httpService/api';
import { Alert, Danger } from 'pages/components/alert';
import Http from 'components/httpService/Http';
import Button from 'components/button';
import SelectBadge from 'components/formik/badge';
import GLOBAL from 'components/variables';
import useHostZones from 'hooks/useHostZones';
import Select from 'components/formik/select';
import FormObserver from 'components/formik/observer';

const pageName = 'Hosts';

const Hosts = () => {
  const createRef = useRef();
  const gridRef = useRef();
  const filterRef = useRef();
  const deleteRef = useRef();
  const copyRef = useRef();
  const testResultRef = useRef();

  const [item, setItem] = useState([]);
  const [isLoadingDelete, setIsLoadingDelete] = useState(false);
  const [isLoadingCopy, setIsLoadingCopy] = useState(false);
  const [isTestingConnection, setIsTestingConnection] = useState(false);
  const [testResult, setTestResult] = useState(null);

  const { hostZones, isLoading: isLoadingZones, getHostZones } = useHostZones();
  useEffect(() => {
    getHostZones();

    return () => {};
  }, []);

  const handleAlert = ({ row }, nameRef) => {
    setItem(row);
    nameRef.current.open();
  };

  const handleEdit = ({ row }) => {
    createRef.current.changeStatus();
    setItem(row);
  };

  const createRow = (data) => {
    gridRef.current.createRow(data);
    setItem({});
  };

  const editRow = (data) => {
    gridRef.current.editRow(data);
    setItem({});
  };

  const handleDelete = () => {
    setIsLoadingDelete(true);
    HttpService()
      .delete(`${api.hosts}/${item?.id}`)
      .then(() => {
        gridRef.current.deleteRow(item);
        deleteRef.current.close();
      })
      .catch((err) => {
        Http.error(err);
      })
      .finally(() => {
        setIsLoadingDelete(false);
      });
  };

  const handleCopy = () => {
    setIsLoadingCopy(true);
    HttpService()
      .post(`${api.hosts}/${item?.id}/copy`)
      .then((res) => {
        gridRef.current.createRow(res.data);
        copyRef.current.close();
      })
      .catch((err) => {
        Http.error(err);
      })
      .finally(() => {
        setIsLoadingCopy(false);
      });
  };

  const handleTestConnection = ({ row }) => {
    setIsTestingConnection(true);
    setItem(row); // Set the current host being tested

    HttpService()
      .post(`${api.middleware}/hosts/${row?.id}/test-connection`)
      .then((res) => {
        console.log(res.data);
        const { result, message, error_type } = res.data;

        setTestResult({
          success: result === 'OK',
          message: message || 'Connection test completed',
          error_type: error_type || null,
          host_name: row?.name || 'Unknown Host',
          host_id: row?.id
        });

        // Open the test result dialog
        testResultRef.current.open();
      })
      .catch((err) => {
        // Handle network/API errors
        let errorMessage = 'Failed to test connection';

        if (err?.response?.data?.message) {
          errorMessage = err.response.data.message;
        } else if (err?.response?.data?.detail) {
          errorMessage = err.response.data.detail;
        } else if (err?.message) {
          errorMessage = err.message;
        } else if (err?.response?.status) {
          errorMessage = `HTTP ${err.response.status}: Connection test failed`;
        }

        setTestResult({
          success: false,
          message: errorMessage,
          error_type: 'NetworkError',
          host_name: row?.name || 'Unknown Host',
          host_id: row?.id
        });

        // Open the test result dialog
        testResultRef.current.open();
      })
      .finally(() => {
        setIsTestingConnection(false);
      });
  };

  const getTestResultTitle = () => {
    if (!testResult) return 'Connection Test';

    return testResult.success
      ? `✅ Connection Successful - ${testResult.host_name}`
      : `❌ Connection Failed - ${testResult.host_name}`;
  };

  const getTestResultContent = () => {
    if (!testResult) return '';

    let content = testResult.message;

    if (!testResult.success && testResult.error_type) {
      content += `\n\nError Type: ${testResult.error_type}`;
    }

    if (testResult.host_id) {
      content += `\nHost ID: ${testResult.host_id}`;
    }

    return content;
  };

  return (
    <>
      <Formik
        initialValues={{
          enable: -1,
          host_id: ''
        }}
        onSubmit={(values) => {
          gridRef.current.filters(values);
          filterRef.current.onChange();
        }}
      >
        <CustomDrawer ref={filterRef}>
          <Form>
            <Stack spacing={1}>
              <SelectBadge name="enable" options={GLOBAL.allEnableStatus} label={'Status'} />
              <Grid container spacing={1}>
                <Grid item xs={9}>
                  <Button fullWidth type={'submit'}>
                    Search
                  </Button>
                </Grid>
                <Grid item xs={3}>
                  <Button color="error" type={'reset'}>
                    reset
                  </Button>
                </Grid>
              </Grid>
            </Stack>
          </Form>
        </CustomDrawer>
      </Formik>

      <Alert
        refrence={copyRef}
        onSubmit={handleCopy}
        onDeleteLoading={isLoadingCopy}
        title={`Are you sure to copy this inbound config?`}
      />

      <Alert
        refrence={testResultRef}
        onSubmit={() => testResultRef.current.close()}
        onSubmitLabel="Close"
      >
        <Box>
          <Typography variant="h6" sx={{ mb: 2 }}>
            {getTestResultTitle()}
          </Typography>
          <Typography
            variant="body1"
            sx={{
              whiteSpace: 'pre-line',
              color: testResult?.success ? 'success.main' : 'error.main',
              fontFamily: 'monospace',
              fontSize: '0.9rem'
            }}
          >
            {getTestResultContent()}
          </Typography>
        </Box>
      </Alert>

      <Danger
        refrence={deleteRef}
        onDelete={handleDelete}
        onDeleteLoading={isLoadingDelete}
        title={`Are you sure want Delete "${item?.name}" ?`}
      />
      <AddEdit
        pageName={pageName}
        refrence={createRef}
        initial={item}
        createRow={createRow}
        editRow={editRow}
      />
      <>
        <Box>
          <Typography variant="h4" gutterBottom>
            {pageName}
          </Typography>
          <Button
            sx={{ mb: 1 }}
            onClick={() => {
              createRef.current.changeStatus();
              setItem('');
            }}
            icon={<Add />}
          >
            Create
          </Button>
        </Box>
        <CustomGrid
          name="hosts"
          url={api.hosts}
          refrence={gridRef}
          columns={columns}
          searchChildren={
            <Formik initialValues={{ zone_id: '0' }}>
              {() => (
                <Form>
                  <FormObserver onChange={(values) => gridRef.current.filters(values)} />
                  <Select
                    size="small"
                    options={[{ id: '0', name: 'All' }, ...hostZones]}
                    isLoading={isLoadingZones}
                    name={'zone_id'}
                  />
                </Form>
              )}
            </Formik>
          }
          moreActions={[
            {
              onClick: (data) => handleTestConnection(data),
              icon: 'info',
              color: 'green',
              name: isTestingConnection ? 'Testing...' : 'Test',
              disabled: isTestingConnection
            },
            {
              onClick: (data) => handleAlert(data, deleteRef),
              icon: 'delete',
              color: 'red',
              name: 'Delete'
            },
            {
              onClick: handleEdit,
              icon: 'edit',
              color: 'primary',
              name: 'Edit'
            },
            {
              onClick: (data) => handleAlert(data, copyRef),
              icon: 'content_copy',
              color: 'primary',
              name: 'Copy'
            }
          ]}
          paginateServ={false}
          showFilter={() => filterRef.current.onChange()}
          sortItem={[
            { id: 'created', name: 'Created' },
            { id: 'modified', name: 'Modified' },
            { id: 'domain', name: 'Domain' },
            { id: 'name', name: 'Name' },
            { id: 'ip', name: 'IP' }
          ]}
          defaultSort={{ value: 'created', ASC: false }}
        />
      </>
    </>
  );
};

export default Hosts;
